   546  static void on_send_complete(h2o_socket_t *sock, const char *err)
   547  {
   548      struct st_h2o_http1_conn_t *conn = sock->data;
   549
   550      assert(conn->req._ostr_top == &conn->_ostr_final.super);
   551
   552      conn->req.timestamps.response_end_at = *h2o_get_timestamp(conn->super.ctx, NULL, NULL);
   553
   554      if (!conn->req.http1_is_persistent) {
   555          /* TODO use lingering close */
   556          close_connection(conn, 1);
   557          return;
   558      }
   559
   560      /* handle next request */
   561      init_request(conn);
   562      h2o_buffer_consume(&conn->sock->input, conn->_reqsize);
   563      conn->_prevreqlen = 0;
   564      conn->_reqsize = 0;
   565      reqread_start(conn);
   566  }
